"""
    Parameters
    ----------
    text: str of nominal values for a single mushroom species from primary_data_edited.csv

    Returns
    -------
    replace commas outside of angular brackets with semicolons (but not inside of them)

    Example
    -------
    text = "[a, b], [c, d]"
    return: "[a, b]; [c, d]"
    """
def replace_comma_in_text(text: Any) -> object {
    result_text = "";
    replace = True;
    for sign in text {
        if (sign == '[') {
            replace = False;
        }
        if (sign == ']') {
            replace = True;
        }
        if (sign == ',') {
            if replace {
                result_text += ';';
            } else {
                result_text += sign;
            }
        } else {
            result_text += sign;
        }
    }
    return result_text;
}

